"""End-to-end pipeline tests against the generated fixtures.

Every planted quirk from the spec is asserted here, plus idempotency,
correction-wins semantics, and exact skip-count accounting.
"""

import json
import sqlite3

import pytest

from evalmerge import db as db_mod
from evalmerge.ingest import STAT_CORRECTIONS, ingest


def _row(conn, run_id, source):
    cur = conn.execute(
        "SELECT run_id, source, model, task, score, stderr, ts_utc, raw_extra "
        "FROM results WHERE run_id = ? AND source = ?",
        (run_id, source),
    )
    cur.row_factory = sqlite3.Row
    return cur.fetchone()


def _rule_count(conn, rule, action=None):
    if action is None:
        sql, params = "SELECT COUNT(*) FROM warnings WHERE rule = ?", (rule,)
    else:
        sql, params = (
            "SELECT COUNT(*) FROM warnings WHERE rule = ? AND action = ?",
            (rule, action),
        )
    return conn.execute(sql, params).fetchone()[0]


class TestIngestCounts:
    def test_rows_ingested_per_source(self, conn, expected):
        per_source = dict(
            conn.execute("SELECT source, COUNT(*) FROM results GROUP BY source")
        )
        assert per_source == expected["ingested"]

    def test_summary_matches_db(self, ingested, conn, expected):
        assert ingested.summary.ingested == expected["ingested"]
        assert ingested.summary.files == expected["files"]

    def test_skip_counts_exactly_match_planted_defects(self, conn, expected):
        skipped = dict(
            conn.execute(
                "SELECT rule, COUNT(*) FROM warnings WHERE action = 'skipped' GROUP BY rule"
            )
        )
        assert skipped == expected["skipped_by_rule"]

    def test_all_warning_counts_match_planted_defects(self, conn, expected):
        warnings = dict(
            conn.execute("SELECT rule, COUNT(*) FROM warnings GROUP BY rule")
        )
        assert warnings == expected["warnings_by_rule"]

    def test_skipped_run_ids_absent_from_results(self, conn, expected):
        skipped_ids = {
            r[0]
            for r in conn.execute(
                "SELECT run_id FROM warnings WHERE action = 'skipped'"
            )
        }
        assert skipped_ids == expected["skipped_run_ids"]
        for run_id in skipped_ids:
            assert (
                conn.execute(
                    "SELECT COUNT(*) FROM results WHERE run_id = ?", (run_id,)
                ).fetchone()[0]
                == 0
            )


class TestFormatAQuirks:
    def test_percentage_and_float_scores(self, conn):
        assert _row(conn, "a-001", "a")["score"] == pytest.approx(0.875)
        assert _row(conn, "a-002", "a")["score"] == pytest.approx(0.91)

    def test_mixed_timestamps_normalized_to_rfc3339(self, conn):
        assert _row(conn, "a-001", "a")["ts_utc"] == "2026-05-01T12:00:00Z"
