        section = report_text.split("Rows skipped per rule")[1].split("\n\n")[0]
        listed = dict(re.findall(r"^  (\S+): (\d+)$", section, flags=re.M))
        assert {k: int(v) for k, v in listed.items()} == expected["skipped_by_rule"]

    def test_nonfatal_warning_counts(self, report_text):
        assert "invalid_meta_json: 2 (kept_raw)" in report_text
        assert "score_out_of_range: 2 (clamped)" in report_text
        assert "unknown_unit: 2 (assumed)" in report_text

    def test_corrections_line(self, report_text, expected):
        assert (
            f"Duplicate corrections applied: {expected['corrections']}" in report_text
        )

