        conn = sqlite3.connect(ingested.db_path)
        try:
            by_model = {}
            for model, score in conn.execute("SELECT model, score FROM results"):
                by_model.setdefault(model, []).append(score)
        finally:
            conn.close()

        pattern = re.compile(
            r"^  (?P<model>\S+): n=(?P<n>\d+)"
            r" min=(?P<min>[\d.]+) median=(?P<median>[\d.]+) max=(?P<max>[\d.]+)$",
            flags=re.M,
        )
        parsed = {m["model"]: m for m in pattern.finditer(report_text)}
        assert set(parsed) == set(by_model)
        for model, scores in by_model.items():
            line = parsed[model]
